"""Data harness runner — CSV/JSONL processing with processed/rejected counting."""

import csv
import json
import os


class HarnessError(Exception):
    """Raised when data processing encounters a fatal error."""
    pass


def _read_csv(filepath):
    """Read CSV file, return list of dict records. Skips blank rows."""
    records = []
    with open(filepath, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if not any(v.strip() for v in row.values() if v):
                continue
            records.append(row)
    return records


def _read_jsonl(filepath):
    """Read JSONL file, return list of dict records. Skips blank lines."""
    records = []
    with open(filepath, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if not stripped:
                continue
            records.append(json.loads(stripped))
    return records


def _count_records(records):
    """Count processed (has non-empty id) and rejected (missing/empty id)."""
    processed = 0
    rejected = 0
    for rec in records:
        id_val = None
        for key in rec:
            if key.lower() == "id":
                id_val = rec[key]
                break
        if id_val is not None and str(id_val).strip():
            processed += 1
        else:
            rejected += 1
    return processed, rejected


def run_dag(source_paths, output_path):
    """Run the data processing DAG.

    Reads every file in *source_paths* (CSV or JSONL), counts processed
    vs. rejected records, and writes a JSON report to *output_path*.

    Raises HarnessError on I/O or parse failures.
    """
    all_records = []
    for path in source_paths:
        try:
            if path.endswith(".jsonl"):
                all_records.extend(_read_jsonl(path))
            else:
                all_records.extend(_read_csv(path))
        except Exception as exc:
            raise HarnessError(f"Failed to read {path}: {exc}") from exc

    processed, rejected = _count_records(all_records)

    report = {
        "processed_count": processed,
        "rejected_count": rejected,
        "retry_count": 0,
        "source_files": list(source_paths),
    }

    out_dir = os.path.dirname(output_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)

    return report

