"""CLI entry point: python -m mini_harness run <files...> --output <path>."""

import sys
from mini_harness.runner import run_dag, HarnessError


def main():
    args = sys.argv[1:]
    if len(args) < 3 or args[0] != "run":
        print(
            "Usage: python -m mini_harness run <input_file>... --output <output_file>",
            file=sys.stderr,
        )
        sys.exit(1)

    rest = args[1:]
    source_files = []
    output_path = None
    i = 0
    while i < len(rest):
        if rest[i] == "--output":
            i += 1
            if i < len(rest):
                output_path = rest[i]
        else:
            source_files.append(rest[i])
        i += 1

    if output_path is None:
        print("Missing --output argument", file=sys.stderr)
        sys.exit(1)

    try:
        result = run_dag(source_files, output_path)
    except HarnessError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

